import Foundation
import KitMermaid
import Testing

/// The port draws each shared fixture exactly as the terminal client's
/// reference renderer does (ADR 0046). The fixtures are generated by the
/// reference: `KIT_UPDATE_MERMAID_FIXTURES=1 ard test test/mermaid_fixtures_test.ard`
/// in `apps/cli`.
struct MermaidFixtureTests {
    /// `testdata/mermaid` at the repository root, five levels above this file.
    static let directory = (0..<5).reduce(URL(fileURLWithPath: #filePath)) { url, _ in
        url.deletingLastPathComponent()
    }.appendingPathComponent("testdata/mermaid")

    static var names: [String] {
        let files = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
        return files.filter { $0.hasSuffix(".mmd") }.map { String($0.dropLast(4)) }.sorted()
    }

    @Test func fixturesArePresent() {
        #expect(Self.names.count > 100)
    }

    @Test(arguments: names) func drawsLikeTheReference(_ name: String) throws {
        let source = try String(contentsOf: Self.directory.appendingPathComponent("\(name).mmd"), encoding: .utf8)
        let expected = try String(contentsOf: Self.directory.appendingPathComponent("\(name).txt"), encoding: .utf8)
        let actual = Self.record(Mermaid.render(source))
        #expect(actual == expected, "\(name)")
    }

    /// A drawing as fixture text, as the reference's harness records it:
    /// its size, its rows, then a row of role letters for each, where capitals
    /// are bold, a blank cell is a space, and a wide character's trailing half is `~`.
    static func record(_ result: Result<Canvas, NotDrawn>) -> String {
        switch result {
        case .failure(let notDrawn):
            return "not drawn: \(notDrawn.reason)\n"
        case .success(let drawing):
            var lines = ["drawn \(drawing.width) \(drawing.height)"]
            lines.append(contentsOf: drawing.lines())
            for y in 0..<drawing.height {
                var row = ""
                for x in 0..<drawing.width {
                    let shown = drawing.shown(x, y)
                    let letter = Self.letter(drawing.role(x, y))
                    row += shown == "" ? "~" : shown == " " ? " " : drawing.isBold(x, y) ? letter.uppercased() : letter
                }
                while row.hasSuffix(" ") { row.removeLast() }
                lines.append(row)
            }
            return lines.joined(separator: "\n") + "\n"
        }
    }

    static func letter(_ role: Role) -> String {
        switch role {
        case .frame: "f"
        case .arrow: "a"
        case .name: "n"
        case .label: "l"
        case .note: "o"
        case .keyword: "k"
        case .condition: "c"
        case .title: "t"
        }
    }
}
